using System.Net;
using System.Net.Sockets;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly HttpListener listener = new();
    private readonly HttpClient client;
    private readonly Uri baseAddress;

    private string? method;
    private string? path;
    private string? contentType;
    private JsonElement sentBody;

    public HttpPaymentGatewayTests()
    {
        var probe = new TcpListener(IPAddress.Loopback, 0);
        probe.Start();
        var port = ((IPEndPoint)probe.LocalEndpoint).Port;
        probe.Stop();

        baseAddress = new Uri($"http://127.0.0.1:{port}/");
        listener.Prefixes.Add(baseAddress.ToString());
        listener.Start();
        client = new HttpClient { BaseAddress = baseAddress };
    }

    private Task<AuthorizationOutcome> AuthorizeAgainst(int status, string? body, Money? amount = null)
    {
        var serve = Task.Run(async () =>
        {
            var context = await listener.GetContextAsync();
            method = context.Request.HttpMethod;
            path = context.Request.Url!.AbsolutePath;
            contentType = context.Request.ContentType;
            using (var reader = new StreamReader(context.Request.InputStream, Encoding.UTF8))
                sentBody = JsonDocument.Parse(await reader.ReadToEndAsync()).RootElement.Clone();

            context.Response.StatusCode = status;
            if (body is not null)
            {
                var bytes = Encoding.UTF8.GetBytes(body);
                context.Response.ContentType = "application/json";
                await context.Response.OutputStream.WriteAsync(bytes);
            }
            context.Response.Close();
        });

        return new HttpPaymentGateway(client)
            .AuthorizeAsync("ORD-7", amount ?? new Money(12.5m, "eur"), CancellationToken.None)
            .ContinueWith(t => { serve.GetAwaiter().GetResult(); return t.GetAwaiter().GetResult(); });
    }

    [Fact]
    public async Task The_request_is_a_json_post_to_the_authorizations_endpoint_with_reference_amount_and_currency()
    {
        await AuthorizeAgainst(200, """{"status":"approved"}""");

        Assert.Equal("POST", method);
        Assert.Equal("/v1/authorizations", path);
        Assert.StartsWith("application/json", contentType);
        Assert.Equal("ORD-7", sentBody.GetProperty("reference").GetString());
        Assert.Equal(12.5m, sentBody.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", sentBody.GetProperty("currency").GetString());
        Assert.Equal(3, sentBody.EnumerateObject().Count());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        Assert.Equal(AuthorizationOutcome.Approved, await AuthorizeAgainst(200, """{"status":"approved"}"""));
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        Assert.Equal(AuthorizationOutcome.Declined, await AuthorizeAgainst(200, """{"status":"declined"}"""));
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        Assert.Equal(AuthorizationOutcome.Approved,
            await AuthorizeAgainst(200, """{"id":"a1","status":"approved","risk":{"score":3}}"""));
    }

    [Theory]
    [InlineData("""{}""")]
    [InlineData("""{"status":null}""")]
    [InlineData("""{"status":"pending"}""")]
    [InlineData("""{"state":"approved"}""")]
    [InlineData("null")]
    public async Task An_answer_that_is_not_an_explicit_approval_is_never_treated_as_approved(string body)
    {
        Assert.Equal(AuthorizationOutcome.Declined, await AuthorizeAgainst(200, body));
    }

    [Fact]
    public async Task A_refusal_with_402_is_a_decline_even_with_an_error_body()
    {
        Assert.Equal(AuthorizationOutcome.Declined,
            await AuthorizeAgainst(402, """{"error":"insufficient_funds"}"""));
    }

    [Fact]
    public async Task A_refusal_with_402_and_no_body_is_a_decline()
    {
        Assert.Equal(AuthorizationOutcome.Declined, await AuthorizeAgainst(402, null));
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_failures_surface_as_errors_instead_of_being_taken_for_a_decision(int status)
    {
        await Assert.ThrowsAsync<HttpRequestException>(() => AuthorizeAgainst(status, """{"status":"approved"}"""));
    }

    [Fact]
    public async Task An_answer_that_is_not_json_surfaces_as_an_error()
    {
        await Assert.ThrowsAsync<JsonException>(() => AuthorizeAgainst(200, "<html>oops</html>"));
    }

    public void Dispose()
    {
        client.Dispose();
        listener.Close();
    }
}
